// Typedef for function signature: returns int, takes a struct pointer
typedef int (*ValidatorFunc)(const struct Payload* p);

struct PluginAPI {
    int id;
    ValidatorFunc validate; // The function pointer slot
};

struct Payload { int data; };

// Function matching the signature
int CheckDataIntegrity(const struct Payload* p) {
    return p->data > 0;
}

// Complex Function Pointer Declaration (no typedef)
void (*ErrorHook(const char* level))(void* data, int code);

// API Registration/Usage
struct PluginAPI P = {
    .id = 1,
    .validate = CheckDataIntegrity
};

// Invocation
struct Payload test = { .data = 10 };
int result = P.validate(&test);
